-- ---- above RM20,000.00, Part F, and the employee side that stops at 60 ------
-- Above the last band KWSP charges the rate on the wage itself: 11% and 12% under
-- Part A, 5.5% and 6% under Part C, 4% employer under Part E. Part F is a rate at
-- any age. These rows keep wage_from_cents just past the last band so the same
-- "highest band the wage reaches" lookup finds them.
insert into public.hr_statutory_rules
  (scheme, payer, citizenship, employee_from_age, employee_until_age, wage_from_cents,
   rate, max_cents, round_to_cents, note) values
  ('epf', 'employee', 'citizen', 0, 60, 2000001, 0.11, null, 1, 'Third Schedule Part A, above RM 20,000'),
  ('epf', 'employer', 'citizen', 0, 60, 2000001, 0.12, null, 1, 'Third Schedule Part A, above RM 20,000'),
  ('epf', 'employee', 'permanent_resident', 0, 60, 2000001, 0.11, null, 1, 'Third Schedule Part A, above RM 20,000'),
  ('epf', 'employer', 'permanent_resident', 0, 60, 2000001, 0.12, null, 1, 'Third Schedule Part A, above RM 20,000'),
  ('epf', 'employee', 'non_citizen_before_1998', 0, 60, 2000001, 0.11, null, 1, 'Third Schedule Part A, above RM 20,000'),
  ('epf', 'employer', 'non_citizen_before_1998', 0, 60, 2000001, 0.12, null, 1, 'Third Schedule Part A, above RM 20,000'),
  ('epf', 'employee', 'permanent_resident', 60, 75, 2000001, 0.055, null, 1, 'Third Schedule Part C, above RM 20,000'),
  ('epf', 'employer', 'permanent_resident', 60, 75, 2000001, 0.06, null, 1, 'Third Schedule Part C, above RM 20,000'),
  ('epf', 'employee', 'non_citizen_before_1998', 60, 75, 2000001, 0.055, null, 1, 'Third Schedule Part C, above RM 20,000'),
  ('epf', 'employer', 'non_citizen_before_1998', 60, 75, 2000001, 0.06, null, 1, 'Third Schedule Part C, above RM 20,000'),
  ('epf', 'employer', 'citizen', 60, 75, 2000001, 0.04, null, 1, 'Third Schedule Part E, above RM 20,000'),
  ('epf', 'employee', 'non_citizen', 0, 75, 0, 0.02, null, 1, 'Third Schedule Part F, any age to 75; mandatory from October 2025 wages'),
  ('epf', 'employer', 'non_citizen', 0, 75, 0, 0.02, null, 1, 'Third Schedule Part F, any age to 75; mandatory from October 2025 wages');

-- ---- a proposed statutory figure ------------------------------------------
-- As in 20261128090000, with the figure taken from the row when the row carries
-- one. A band row has no rate and a maximum would be meaningless beside a fixed
-- amount, so LEAST ignores the null and the band's amount comes straight back.
-- A rate row answers exactly as it did, which is what SOCSO and EIS still are.
create or replace function private.hr_payroll_proposal(
  p_scheme text, p_wage_cents bigint, p_age int, p_citizenship text, p_payer text default 'employee')
returns bigint language sql stable set search_path = public as $$
  select coalesce((
    select least(
             coalesce(s.amount_cents,
                      round(p_wage_cents * s.rate / s.round_to_cents) * s.round_to_cents)::bigint,
             s.max_cents)::bigint
    from public.hr_statutory_rules s
    where s.scheme = p_scheme
      and s.payer = coalesce(p_payer, 'employee')
      and s.citizenship = coalesce(p_citizenship, 'citizen')
      and s.wage_from_cents <= coalesce(p_wage_cents, 0)
      and case
        when p_age is null then s.employee_from_age <= 18 and coalesce(s.employee_until_age, 1000) >= 60
        else p_age >= s.employee_from_age and p_age < coalesce(s.employee_until_age, 1000)
      end
    order by s.wage_from_cents desc
    limit 1
  ), 0);
$$;
revoke all on function private.hr_payroll_proposal(text, bigint, int, text, text) from public, anon, authenticated;

